/* From Uiverse.io by JaydipPrajapati1910 - Tags: loading, loader, line, line loader */
.__UIV_SCOPE__ .container {
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .container div {
  position: absolute;
  width: 90px;
  height: 51px;
}

.__UIV_SCOPE__ .container div:nth-of-type(2) {
  transform: rotate(60deg)
}

.__UIV_SCOPE__ .container div:nth-of-type(3) {
  transform: rotate(-60deg)
}

.__UIV_SCOPE__ .container div div {
  width: 100%;
  height: 100%;
  position: relative
}

.__UIV_SCOPE__ .container div div span {
  position: absolute;
  width: 4px;
  height: 0%;
  background: #053146;
  z-index: 999999;
}

.__UIV_SCOPE__ .h1 {
  left: 0;
  animation: load1 7.2s ease infinite;
}

.__UIV_SCOPE__ .h2 {
  right: 0;
  animation: load2 7.2s ease .6s infinite;
}

.__UIV_SCOPE__ .h3 {
  right: 0;
  animation: load3 7.2s ease 1.2s infinite;
}

.__UIV_SCOPE__ .h4 {
  right: 0;
  animation: load4 7.2s ease 1.8s infinite;
}

.__UIV_SCOPE__ .h5 {
  left: 0;
  animation: load5 7.2s ease 2.4s infinite;
}

.__UIV_SCOPE__ .h6 {
  left: 0;
  animation: load6 7.2s ease 3s infinite;
}

@keyframes load1 {
  0% {
    bottom: 0;
    height: 0
  }

  6.944444444% {
    bottom: 0;
    height: 100%
  }

  50% {
    top: 0;
    height: 100%
  }

  59.944444433% {
    top: 0;
    height: 0
  }
/*   91.6666667%{top:0;height:0%;} */
}

